create table if not exists camera_events (id uuid primary key default gen_random_uuid(), room_id uuid references classroom_rooms(id) on delete cascade, user_id uuid, event_type text not null check (event_type in ('on','off')), started_at timestamptz, ended_at timestamptz, duration_seconds int default 0, created_at timestamptz default now()); alter table camera_events enable row level security; create index if not exists idx_camera_events_room on camera_events(room_id);
